let orders;
try {
  orders = $input.all().map(item => item.json);

  if (orders.length === 0) {
    return [{
      json: {
        summary_data: {
          status: "no_orders",
          message: "No orders were updated today.",
          timestamp: new Date().toISOString(),
          metrics:{
            total_orders: 0
          }
        }
      }
    }];
  }

  const todayStart = $now.startOf('day').toJSDate();

  const summary = {
    new_orders: [],
    shipped: [],
    returned_refunded: [],
    cancelled: [],
    other_pending: [],
    metrics: {
      total_orders: orders.length,
      new_orders_count: 0,
      updated_orders_count: 0,
      total_revenue: 0,
      new_orders_revenue: 0,
      average_order_value: 0,
      fulfillment_rate: 0,
      cancellation_rate: 0,
      refund_rate: 0
    },
    timestamp: new Date().toISOString(),
    date: $now.toFormat('yyyy-MM-dd') 
  };

  orders.forEach(order => {
    if (!order.id || !order.order_number) {
      console.log('Invalid order found:', order);
      return {};
    }

    const isNewOrder = new Date(order.created_at) >= todayStart;

    const details = {
      order_number: order.order_number,
      order_id: order.id,
      total_price: parseFloat(order.current_total_price || 0),
      currency: order.currency || 'USD',
      created_at: order.created_at,
      updated_at: order.updated_at,
      customer_email: order.customer?.email || 'N/A',
      is_new_order: isNewOrder
    };

    // Revenue
    summary.metrics.total_revenue += details.total_price;
    if (isNewOrder) {
      summary.metrics.new_orders_revenue += details.total_price;
      summary.new_orders.push(details);
    }

    // Categorization
    if (order.cancelled_at !== null || order.cancel_reason) {
      details.reason = order.cancel_reason || 'Not specified';
      details.cancelled_at = order.cancelled_at;
      summary.cancelled.push(details);
    }
    else if (order.financial_status === 'refunded' || order.financial_status === 'partially_refunded') {
      details.financial_status = order.financial_status;
      details.refund_count = order.refunds ? order.refunds.length : 0;
      details.refund_amount = order.refunds?.reduce((sum, r) => sum + (r.amount || 0), 0) || 0;
      summary.returned_refunded.push(details);
    }
    else if (order.fulfillment_status === 'fulfilled' && order.fulfillments?.length > 0) {
      details.fulfillment_status = order.fulfillment_status;
      details.fulfillment_count = order.fulfillments.length;
      details.tracking_numbers = order.fulfillments.map(f => f.tracking_number || 'None');
      details.estimated_delivery = order.fulfillments[0]?.estimated_delivery_date || 'Unknown';
      summary.shipped.push(details);
    }
    else {
      details.financial_status = order.financial_status || 'pending';
      details.fulfillment_status = order.fulfillment_status || 'unfulfilled';
      details.is_closed = order.closed_at !== null;
      details.days_pending = Math.floor((new Date() - new Date(order.created_at)) / (1000 * 60 * 60 * 24));
      summary.other_pending.push(details);
    }
  });

  // Calculate metrics
  summary.metrics.new_orders_count = summary.new_orders.length;
  summary.metrics.updated_orders_count = orders.length - summary.new_orders.length;
  summary.metrics.average_order_value = (summary.metrics.total_revenue / orders.length).toFixed(2);
  summary.metrics.fulfillment_rate = ((summary.shipped.length / orders.length) * 100).toFixed(2) + '%';
  summary.metrics.cancellation_rate = ((summary.cancelled.length / orders.length) * 100).toFixed(2) + '%';
  summary.metrics.refund_rate = ((summary.returned_refunded.length / orders.length) * 100).toFixed(2) + '%';

  return [{ json: { summary_data: summary } }];

} catch (error) {
  console.log("Error reading orders:", error.message);
  return [{
    json: {
      summary_data: {
        status: "error",
        message: "Failed to read Shopify orders: " + error.message,
        timestamp: new Date().toISOString(),
        metrics: {
          total_orders: 0
        }
      }
    }
  }];
}
